import {chromium} from '@playwright/test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {KEY,scenarioState} from '../src/model.js';
const base='http://127.0.0.1:5184',dir='检查记录/我的画像_20261021';
const b=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']});
const p=await b.newPage({viewport:{width:1440,height:1000}}),errors=[],results=[];
p.setDefaultTimeout(8000);p.on('pageerror',e=>errors.push(e.message));
async function load(s,lang='zh',width=1440){await p.setViewportSize({width,height:width<720?844:1000});await p.goto(base);await p.evaluate(({s,k,lang})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true,active:null,seen:[]}));},{s,k:KEY,lang});await p.goto(base+'/assessment?tab=我的画像');await p.locator('.profile-insight-ring').waitFor();await p.emulateMedia({reducedMotion:'reduce'});await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});const toast=p.locator('.toast.show button');if(await toast.count())await toast.click();}
async function check(name,fn){try{await fn();results.push({name,status:'pass'});console.log('PASS',name);}catch(e){results.push({name,status:'fail',error:e.message});console.log('FAIL',name,e.message.slice(0,500));}}
async function shot(name){await p.locator('#main').evaluate(e=>e.scrollTop=0);await p.screenshot({path:dir+'/'+name+'-视口.png'});await p.locator('.profile-insight').evaluate(e=>e.scrollIntoView({block:'start'}));await p.screenshot({path:dir+'/'+name+'-区域视口.png'});const v=p.viewportSize(),box=await p.locator('.profile-insight').boundingBox();await p.setViewportSize({width:v.width,height:Math.ceil(box.height+600)});await p.addStyleTag({content:'.flow-progress{visibility:hidden!important}'}).then(async style=>{await p.locator('.profile-insight').screenshot({path:dir+'/'+name+'-板块.png'});await style.evaluate(e=>e.remove());});await p.setViewportSize(v);}
try{
await check('空态显示0/4与具体起点，四维支持键盘切换',async()=>{await load(scenarioState('PT01'));assert.match(await p.locator('.profile-insight-ring-count').textContent(),/0.*4/);assert.equal(await p.locator('.profile-insight-arc.missing').count(),4);assert.equal(await p.locator('.profile-insight-gaps li').count(),3);assert.equal(await p.locator('.profile-insight-filters').count(),0);await p.getByRole('button',{name:/BR.*条件与可行性/}).focus();await p.keyboard.press('Enter');assert.equal(await p.getByRole('button',{name:/BR.*条件与可行性/}).getAttribute('aria-pressed'),'true');assert.match(await p.locator('.profile-insight-detail').textContent(),/岗位.*仍待了解/);await p.locator('.profile-insight-sector').nth(3).focus();await p.keyboard.press('Space');assert.match(await p.locator('.profile-insight-detail h3').textContent(),/学习与改进/);await shot('1440-空画像');});
await check('有记录时来源可查，四态筛选不丢弃撤回记录',async()=>{const s=scenarioState('PT05');s.claims.push({...s.claims[0],id:'pending',title:'待确认的合成材料',status:'待确认'},{...s.claims[0],id:'withdrawn',title:'撤回的合成材料',status:'已撤回'});await load(s);assert.equal(await p.locator('.profile-insight-arc.recorded').count(),3);assert.equal(await p.locator('.profile-insight-records>li').count(),4);await p.getByRole('button',{name:/未采用 \/ 已撤回/}).click();assert.equal(await p.locator('.profile-insight-records>li').count(),1);assert.match(await p.locator('.profile-insight-records').textContent(),/撤回的合成材料/);await p.getByRole('button',{name:/^已确认/}).click();assert.equal(await p.locator('.profile-insight-records>li').count(),2);await p.getByRole('button',{name:/TQ.*行为与协作/}).click();assert.match(await p.locator('.profile-insight-detail').textContent(),/不等于协作能力证明/);await shot('1440-已有材料');});
await check('职业范围改变后重新提示关联材料，不修改原始经历',async()=>{await p.locator('.assessment-context select').selectOption('ops');assert.match(await p.locator('.profile-insight-gaps').textContent(),/运维工程/);assert.match(await p.locator('.profile-insight-gaps').textContent(),/Linux/);assert.equal(await p.locator('.profile-insight-counts dd').nth(1).textContent(),'0 项 · Linux');});
await check('四维都有记录时不给虚构短板或能力分数',async()=>{const s=scenarioState('PT05');s.reviews=[{id:'r1',type:'合成复盘',result:'记录失败原因',next:'补充限制'}];await load(s);assert.equal(await p.locator('.profile-insight-arc.recorded').count(),4);assert.equal(await p.locator('.profile-insight-gaps li').count(),0);assert.equal(await p.locator('.profile-insight-next').count(),1);await shot('1440-四维记录');});
await check('空态、长文本手机与英文均不横向溢出，底部动作可达',async()=>{for(const [name,s,lang]of [['390-空画像',scenarioState('PT01'),'zh'],['390-已有材料',scenarioState('PT05'),'zh'],['390-English',scenarioState('PT01'),'en']]){if(name==='390-已有材料')s.claims[0].title='测试一个很长的经历标题与输出路径'.repeat(8);await load(s,lang,390);assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.equal(await p.locator('.profile-insight').evaluate(e=>e.scrollWidth>e.clientWidth),false);if(lang==='en'){assert.match(await p.locator('.profile-insight-heading').textContent(),/Four-dimensional records/);assert.equal((await p.locator('.profile-insight').innerText()).match(/[\u4e00-\u9fff]/g),null);}await shot(name);const last=p.locator('.profile-insight-archive').locator('a').last();await last.scrollIntoViewIfNeeded();await p.screenshot({path:dir+'/'+name+'-底部.png'});const a=await last.boundingBox(),flow=await p.locator('.flow-progress').boundingBox();assert.ok(a.y+a.height<flow.y+1);}});
await check('待补操作进入现有业务页，画像查看不写入能力判断',async()=>{await load(scenarioState('PT01'));await p.locator('.profile-insight-detail a').first().click();await p.waitForURL(u=>u.pathname==='/assessment'&&!u.searchParams.get('tab'));await load(scenarioState('PT01'));await p.getByRole('button',{name:/BR.*条件与可行性/}).click();await p.getByRole('link',{name:'补充工作条件 →',exact:true}).click();await p.waitForURL(u=>u.pathname==='/settings');const state=await p.evaluate(k=>JSON.parse(localStorage.getItem(k)),KEY);assert.equal(state.analysis,null);assert.equal(state.claims.length,0);});
assert.equal(errors.length,0);results.push({name:'浏览器运行时错误',status:'pass',count:errors.length});
}finally{await fs.writeFile(dir+'/浏览器验收.json',JSON.stringify({results,errors},null,2));await b.close();}
if(results.some(r=>r.status==='fail'))process.exitCode=1;
